import{_ as s,o,c as a,a3 as t}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tenant API v1 — Expenses","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Expenses | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-expenses"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Expenses | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-expenses"}]]},"headers":[],"relativePath":"api/tenant-v1-expenses.md","filePath":"api/tenant-v1-expenses.md","lastUpdated":1787698014000}'),d={name:"api/tenant-v1-expenses.md"};function n(i,e,c,r,p,l){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-expenses" tabindex="-1">Tenant API v1 — Expenses <a class="header-anchor" href="#tenant-api-v1-—-expenses" aria-label="Permalink to &quot;Tenant API v1 — Expenses&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:expenses</code>, plus permission middleware / policies.</p><p>No hard <code>module_dependencies</code> — Expenses installs standalone. <code>vendor_id</code> and <code>purchase_order_id</code> are optional; supplying either requires the corresponding module (<code>vendors</code> / <code>purchase-orders</code>) to be entitled on the workspace, enforced by <code>LinkableVendor</code> / <code>LinkablePurchaseOrder</code>.</p><p>Assignee scoping: without <code>expenses.assign</code> (and not superadmin), list/stats/view/update/<strong>submit</strong>/<strong>cancel</strong> only include expenses where <code>assigned_to</code> is the current user. <code>approve</code>/<code>reject</code>/<code>pay</code> are <strong>not</strong> assignee-scoped — any actor holding the specific permission may act on any expense they can otherwise view.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-expenses-stats" tabindex="-1">GET <code>/expenses/stats</code> <a class="header-anchor" href="#get-expenses-stats" aria-label="Permalink to &quot;GET `/expenses/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_expenses&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_expenses&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;submitted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;approved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rejected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cancelled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;approved_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paid_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="expenses-crud" tabindex="-1">Expenses CRUD <a class="header-anchor" href="#expenses-crud" aria-label="Permalink to &quot;Expenses CRUD&quot;">​</a></h2><h3 id="get-expenses" tabindex="-1">GET <code>/expenses</code> <a class="header-anchor" href="#get-expenses" aria-label="Permalink to &quot;GET `/expenses`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code> (<code>draft</code>|<code>submitted</code>|<code>approved</code>|<code>rejected</code>|<code>paid</code>|<code>cancelled</code>), <code>category_id</code>, <code>vendor_id</code>, <code>purchase_order_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_expenses</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>category_id</code>, embedded <code>category</code> (<code>{ id, name, slug }</code> when loaded), <code>amount</code>, <code>tax_amount</code>, <code>currency</code>, <code>expense_date</code>, <code>vendor</code>/<code>purchase_order</code> refs (when linked), assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-expenses" tabindex="-1">POST <code>/expenses</code> <a class="header-anchor" href="#post-expenses" aria-label="Permalink to &quot;POST `/expenses`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>category_id</code> (optional — tenant <code>expense_categories</code> id, must be active; defaults to the seeded <strong>Other</strong> category), <code>amount</code> (required), <code>tax_amount</code> (optional, default <code>0</code>), <code>currency</code> (3-letter, default <code>USD</code>), <code>expense_date</code>, <code>notes</code>, <code>vendor_id</code> (optional — must belong to the tenant and the Vendors module must be entitled), <code>purchase_order_id</code> (optional — must belong to the tenant and the Purchase Orders module must be entitled), <code>assigned_to</code>.</p><p>Optional multipart field <code>receipt</code> (file, max 5120 KB): jpg/jpeg/png/gif/webp/pdf/txt/log. Stored as <code>ExpenseAttachment</code>; bytes count toward workspace Storage quota (<code>WorkspaceStorageService::assertCanStore</code>). Returns <code>attachments</code> array on the expense resource.</p><p>Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>EXP-00001</code>, configurable via the <code>expenses_number_prefix</code> tenant setting). There is no server-computed total — <code>amount</code> and <code>tax_amount</code> are stored as given.</p><h3 id="get-expenses-id" tabindex="-1">GET <code>/expenses/{id}</code> <a class="header-anchor" href="#get-expenses-id" aria-label="Permalink to &quot;GET `/expenses/{id}`&quot;">​</a></h3><p>Includes vendor, purchase order, assignee, creator, notes, timeline activities, and <code>attachments</code> (<code>uuid</code>, <code>original_name</code>, <code>mime</code>, <code>size_bytes</code>, <code>created_at</code>). Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="put-expenses-id" tabindex="-1">PUT <code>/expenses/{id}</code> <a class="header-anchor" href="#put-expenses-id" aria-label="Permalink to &quot;PUT `/expenses/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> expenses only. Non-draft expenses return 422 on <code>status</code> (<code>Only draft expenses can be edited.</code>). Assignment after submit uses <code>POST /expenses/{id}/assign</code>.</p><p>Optional <code>receipt</code> on draft update uses the same validation as create. For multipart file upload, use <code>POST /expenses/{id}</code> (POST twin) — PHP does not populate uploaded files on true HTTP PUT.</p><h3 id="get-expenses-attachments-uuid-download" tabindex="-1">GET <code>/expenses/attachments/{uuid}/download</code> <a class="header-anchor" href="#get-expenses-attachments-uuid-download" aria-label="Permalink to &quot;GET `/expenses/attachments/{uuid}/download`&quot;">​</a></h3><p>Permission: parent expense <code>view</code> via <code>ExpenseAttachmentPolicy</code>. Returns the stored file as a download (<code>original_name</code>). 404 if the file is missing on disk.</p><h3 id="delete-expenses-id" tabindex="-1">DELETE <code>/expenses/{id}</code> <a class="header-anchor" href="#delete-expenses-id" aria-label="Permalink to &quot;DELETE `/expenses/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>expenses.delete</code>.</p><h3 id="post-expenses-id-restore" tabindex="-1">POST <code>/expenses/{id}/restore</code> <a class="header-anchor" href="#post-expenses-id-restore" aria-label="Permalink to &quot;POST `/expenses/{id}/restore`&quot;">​</a></h3><p>Permission: <code>expenses.restore</code>.</p><h3 id="delete-expenses-id-force" tabindex="-1">DELETE <code>/expenses/{id}/force</code> <a class="header-anchor" href="#delete-expenses-id-force" aria-label="Permalink to &quot;DELETE `/expenses/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted expense. Permission: <code>expenses.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-expenses-id-assign" tabindex="-1">POST <code>/expenses/{id}/assign</code> <a class="header-anchor" href="#post-expenses-id-assign" aria-label="Permalink to &quot;POST `/expenses/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>expenses.assign</code>.</p><h3 id="post-expenses-id-submit" tabindex="-1">POST <code>/expenses/{id}/submit</code> <a class="header-anchor" href="#post-expenses-id-submit" aria-label="Permalink to &quot;POST `/expenses/{id}/submit`&quot;">​</a></h3><p>Transitions <code>draft → submitted</code>. Permission: <code>expenses.submit</code> (assignee-scoped unless the actor has <code>expenses.assign</code> or is superadmin).</p><h3 id="post-expenses-id-approve" tabindex="-1">POST <code>/expenses/{id}/approve</code> <a class="header-anchor" href="#post-expenses-id-approve" aria-label="Permalink to &quot;POST `/expenses/{id}/approve`&quot;">​</a></h3><p>Transitions <code>submitted → approved</code>. Permission: <code>expenses.approve</code> (not assignee-scoped).</p><h3 id="post-expenses-id-reject" tabindex="-1">POST <code>/expenses/{id}/reject</code> <a class="header-anchor" href="#post-expenses-id-reject" aria-label="Permalink to &quot;POST `/expenses/{id}/reject`&quot;">​</a></h3><p>Transitions <code>submitted → rejected</code> (terminal). Permission: <code>expenses.reject</code> (not assignee-scoped).</p><h3 id="post-expenses-id-pay" tabindex="-1">POST <code>/expenses/{id}/pay</code> <a class="header-anchor" href="#post-expenses-id-pay" aria-label="Permalink to &quot;POST `/expenses/{id}/pay`&quot;">​</a></h3><p>Transitions <code>approved → paid</code> (terminal). Permission: <code>expenses.pay</code> (not assignee-scoped).</p><p>Body (optional unless Accounting is entitled): <code>paid_from_account_id</code> (required active cash/bank when Accounting installed), <code>expense_account_id</code> (optional expense-type account; defaults to system Operating Expenses <code>6000</code>). When Accounting is entitled, creates a posted journal (<strong>Dr</strong> expense / <strong>Cr</strong> paid-from) for <code>amount + tax_amount</code> and sets <code>journal_entry_id</code>.</p><h3 id="post-expenses-id-cancel" tabindex="-1">POST <code>/expenses/{id}/cancel</code> <a class="header-anchor" href="#post-expenses-id-cancel" aria-label="Permalink to &quot;POST `/expenses/{id}/cancel`&quot;">​</a></h3><p>Transitions <code>draft|submitted → cancelled</code> (terminal). Permission: <code>expenses.cancel</code> (assignee-scoped unless the actor has <code>expenses.assign</code> or is superadmin).</p><h3 id="post-expenses-id-status" tabindex="-1">POST <code>/expenses/{id}/status</code> <a class="header-anchor" href="#post-expenses-id-status" aria-label="Permalink to &quot;POST `/expenses/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;submitted&quot;|&quot;approved&quot;|&quot;rejected&quot;|&quot;paid&quot;|&quot;cancelled&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>submitted</code> → <code>expenses.submit</code></li><li><code>approved</code> → <code>expenses.approve</code></li><li><code>rejected</code> → <code>expenses.reject</code></li><li><code>paid</code> → <code>expenses.pay</code></li><li><code>cancelled</code> → <code>expenses.cancel</code></li><li>other → <code>expenses.update</code></li></ul><p>Rejects disallowed transitions with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry.</p><h3 id="post-expenses-id-notes" tabindex="-1">POST <code>/expenses/{id}/notes</code> <a class="header-anchor" href="#post-expenses-id-notes" aria-label="Permalink to &quot;POST `/expenses/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>expenses.update</code>.</p><h3 id="get-expenses-id-timeline" tabindex="-1">GET <code>/expenses/{id}/timeline</code> <a class="header-anchor" href="#get-expenses-id-timeline" aria-label="Permalink to &quot;GET `/expenses/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p><h2 id="expense-categories" tabindex="-1">Expense categories <a class="header-anchor" href="#expense-categories" aria-label="Permalink to &quot;Expense categories&quot;">​</a></h2><p>Categories use the same <code>module:expenses</code> gate and <code>expenses.*</code> permissions (no separate permission family). Listing lazy-seeds Travel / Office / Software / Utilities / Other when missing. Starter slugs (<code>travel|office|software|utilities|other</code>) are not changed on rename. Listing does not restore a soft-deleted starter except <strong>Other</strong>.</p><ul><li><code>GET /expense-categories</code> — list (<code>expenses.view</code>)</li><li><code>POST /expense-categories</code> — create (<code>expenses.create</code>). Body: <code>name</code> (required); optional <code>slug</code>, <code>sort_order</code>, <code>is_active</code></li><li><code>GET|PUT|DELETE /expense-categories/{expenseCategory}</code> — view, update, soft-delete (<code>view</code> / <code>update</code> / <code>delete</code>)</li><li><code>POST /expense-categories/{expenseCategory}/restore</code> — restore (<code>expenses.restore</code>)</li><li><code>DELETE /expense-categories/{expenseCategory}/force</code> — permanently delete a soft-deleted category (<code>expenses.force.delete</code>)</li></ul><p>Delete and force-delete return 422 if the category slug is <code>other</code>, or if any expenses (including trashed, for force) still reference the category.</p><h2 id="related-convert-a-purchase-order-to-an-expense" tabindex="-1">Related: convert a Purchase Order to an Expense <a class="header-anchor" href="#related-convert-a-purchase-order-to-an-expense" aria-label="Permalink to &quot;Related: convert a Purchase Order to an Expense&quot;">​</a></h2><h3 id="post-purchase-orders-id-convert" tabindex="-1">POST <code>/purchase-orders/{id}/convert</code> <a class="header-anchor" href="#post-purchase-orders-id-convert" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/convert`&quot;">​</a></h3><p>Documented under <a href="/api/tenant-v1-purchase-orders#convert-to-expense-soft-dependency-on-expenses">Tenant Purchase Orders — Convert to expense</a>. Requires the Expenses module to be entitled (soft check — 422 if not) and the <code>purchase-orders.convert</code> permission. Returns the newly created draft <code>Expense</code> (201).</p>',62)])])}const x=s(d,[["render",n]]);export{u as __pageData,x as default};
